function streetKey(s){return String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"")}
function planPassState(x,p){let done=[p.pass1_done,p.pass2_done,p.pass3_done].slice(0,x.passes).filter(Number).length;return {done,current:x.passes?Math.min(done+1,x.passes):0,all:x.passes===0||done>=x.passes}}
async function field(p){
  let [live,progress,doorPassSummary]=await Promise.all([getJSON("/api/field-plan"),getJSON("/api/street-progress"),getJSON("/api/door-pass-summary")]),
      lm=new Map(live.map(x=>[streetKey(x.street),x])),pm=new Map(progress.map(x=>[streetKey(x.street),x])),dm=new Map(doorPassSummary.map(x=>[streetKey(x.street),x]));
  let build=x=>{let l=lm.get(streetKey(x.street))||{},pr=pm.get(streetKey(x.street))||{},d=dm.get(streetKey(x.street))||{};
    let passDone=x.passes===0?0:([1,2,3].slice(0,x.passes).filter(n=>Number(d["pass"+n+"_count"]||0)>=x.doors).length),currentPass=x.passes?Math.min(passDone+1,x.passes):0,currentPassCount=currentPass?Number(d["pass"+currentPass+"_count"]||0):0,currentPassPct=x.doors&&currentPass?Math.min(100,Math.round(100*currentPassCount/x.doors)):0;
    return {...x,...pr,precincts:String(l.precincts||""),confirmed:Number(l.supporters||0),doorsKnocked:Number(l.doors_knocked||0),housesKnocked:Number(l.houses_knocked||0),votersReached:Number(l.voters_reached||0),passDone,currentPass,currentPassPct,lastKnock:l.last_knock_date||"",pct:x.target?Math.min(100,100*Number(l.supporters||0)/x.target):(Number(l.supporters||0)>0?100:0)}};
  let all=FIELD_PLAN.map(build),precinctMatch=x=>window.fieldPrecinct==="All"||(window.fieldPrecinct==="2828_2833"?x.precincts.split(",").some(p=>p==="2828"||p==="2833"):x.precincts.split(",").includes(window.fieldPrecinct)),precinctRows=all.filter(precinctMatch),rows=precinctRows.filter(x=>window.fieldTier==="All"||x.tier===window.fieldTier),confirmed=precinctRows.reduce((a,x)=>a+x.confirmed,0),knocked=precinctRows.reduce((a,x)=>a+x.doorsKnocked,0);
  let tierConfirmed=t=>precinctRows.filter(x=>x.tier===t).reduce((a,x)=>a+x.confirmed,0);
  const rank={"1A":1,"1B":2,"2":3,"3":4};
  rows.sort((a,b)=>window.fieldPlanSort==="target"?b.target-a.target:window.fieldPlanSort==="pct"?a.pct-b.pct:window.fieldPlanSort==="doors"?b.doors-a.doors:(rank[a.tier]-rank[b.tier]||a.pct-b.pct||a.street.localeCompare(b.street)));
  let top='<div class="fieldRollup"><b>CONFIRMED '+confirmed.toLocaleString()+'/1,000 · DOORS '+knocked.toLocaleString()+'/4,365</b><span>1A '+tierConfirmed("1A")+'/414 &nbsp; 1B '+tierConfirmed("1B")+'/263 &nbsp; 2 '+tierConfirmed("2")+'/237 &nbsp; 3 '+tierConfirmed("3")+'/5</span></div>';
  let nav='';
  let sorts='<div class="fieldPlanSort"><button data-plan-sort="tier" class="'+(window.fieldPlanSort==="tier"?"active":"")+'">Tier ↑</button><button data-plan-sort="target" class="'+(window.fieldPlanSort==="target"?"active":"")+'">Target ↓</button><button data-plan-sort="pct" class="'+(window.fieldPlanSort==="pct"?"active":"")+'">% Done ↑</button><button data-plan-sort="doors" class="'+(window.fieldPlanSort==="doors"?"active":"")+'">Doors ↓</button></div>';
  let chips='<div class="tierChips">'+["All","1A","1B","2","3"].map(t=>'<button data-tier-filter="'+t+'" class="tier-'+t.replace("A","a").replace("B","b")+' '+(window.fieldTier===t?"active":"")+'">'+(t==="All"?"All":"Tier "+t)+'</button>').join("")+'</div>';
  let precinct='<div class="fieldPrecinct"><select id="fieldPrecinctSelect"><option value="All">All Precincts</option><option value="2827">2827 · Juanita Sanchez</option><option value="2828_2833">2828 + 2833 · Washington Park</option><option value="2832">2832 · RW Casino</option></select></div>';
  $("#summary").innerHTML="";$("#content").innerHTML='<div class="fieldPage">'+nav+top+precinct+sorts+chips+'<div class="fieldCards">'+rows.map(x=>{let m=tierMeta[x.tier],alpha=(0.04+0.20*x.pct/100).toFixed(2);return '<div class="fieldPlanCard" data-open-street="'+esc(x.street)+'" style="--tier:'+m.rgb+';--alpha:'+alpha+'"><div class="planHead"><b>'+esc(x.street)+'</b><span>Tier '+x.tier+'</span></div><div class="planStats">'+x.votersReached+'/'+x.voters+' Voters · '+x.doorsKnocked+'/'+x.doors+' Doors · '+x.housesKnocked+'/'+x.houses+' Houses · '+x.confirmed+'/'+x.target+' Target · '+(x.passes?'Pass '+x.currentPass+'/'+x.passes+' '+x.currentPassPct+'%':'Pass 0/0')+'</div></div>'}).join("")+'</div></div>';let fps=$("#fieldPrecinctSelect");if(fps)fps.value=window.fieldPrecinct;
}
async function setFieldSort(b){let key=b.dataset.fieldkey,def=key==="street"?"asc":"desc";window.fieldSortDir=window.fieldSortKey===key?(window.fieldSortDir==="asc"?"desc":"asc"):def;window.fieldSortKey=key;await field(new URLSearchParams())}
